<?php
require __DIR__.'/common.php'; admin_require_login(); $msg=''; $backupDir=$storage.'/backups'; if(!is_dir($backupDir))@mkdir($backupDir,0700,true);
if($_SERVER['REQUEST_METHOD']==='POST') { admin_verify_csrf(); $name='karsabt-'.date('Ymd-His').'-'.bin2hex(random_bytes(3)).'.sql'; $dest=$backupDir.'/'.$name; try { $out="-- Karsabt MySQL backup\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n"; $tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_NUM); foreach($tables as $t){$table=$t[0];$create=$pdo->query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM);$out.="\nDROP TABLE IF EXISTS `{$table}`;\n".$create[1].";\n"; $rows=$pdo->query('SELECT * FROM `'.$table.'`'); while($row=$rows->fetch(PDO::FETCH_ASSOC)){ $cols=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($row)); $vals=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row)); $out.='INSERT INTO `'.$table.'` ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n"; } } $out.="SET FOREIGN_KEY_CHECKS=1;\n"; if(file_put_contents($dest,$out,LOCK_EX)===false)throw new RuntimeException('write failed'); @chmod($dest,0600); $msg='بکاپ SQL ایجاد شد: '.$name; $files=glob($backupDir.'/karsabt-*.sql')?:[]; usort($files,fn($a,$b)=>filemtime($b)<=>filemtime($a)); foreach(array_slice($files,5) as $old)@unlink($old); } catch(Throwable $e){error_log('Karsabt backup: '.$e->getMessage());$msg='ساخت بکاپ ناموفق بود؛ فضای ذخیره‌سازی و مجوز پوشه را بررسی کنید.';} }
$files=glob($backupDir.'/karsabt-*.sql')?:[]; usort($files,fn($a,$b)=>filemtime($b)<=>filemtime($a)); admin_header('پشتیبان‌گیری دیتابیس'); ?><section class="card"><p><?=admin_e($msg)?></p><p>خروجی استاندارد SQL از MySQL در پوشه خصوصی خارج از public_html ذخیره می‌شود. حداکثر ۵ نسخه آخر نگهداری خواهد شد. برای بازیابی، فایل SQL را از طریق phpMyAdmin در دیتابیس انتخاب‌شده وارد کنید.</p><form method="post"><input type="hidden" name="csrf" value="<?=admin_e(admin_csrf())?>"><button>ایجاد بکاپ اکنون</button></form><h2>بکاپ‌های موجود</h2><?php if(!$files):?><p>هنوز بکاپی موجود نیست.</p><?php else:foreach($files as $f):?><p><?=admin_e(basename($f))?> — <?=number_format(filesize($f))?> bytes — <?=date('Y-m-d H:i',filemtime($f))?></p><?php endforeach;endif?></section></main></html>
